"""Migration of Meridian CRM 4.2 order_fulfilment workflow."""

from typing import Any


def _lookup_credit_hold(record: dict, tables: dict) -> str:
    """Return CRED_HOLD from the first live matching ACCT_MASTER row."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG", "") != "Y" and row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def _positive_total(record: dict) -> bool:
    """Implement NVL(TOT_AMT, 0) > 0 for relevant legacy values."""
    value: Any = record.get("TOT_AMT", "")
    if value is None or value == "":
        value = 0
    try:
        return float(value) > 0
    except (TypeError, ValueError):
        return False


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire one order_fulfilment workflow event."""
    result_record = dict(record)

    if state == "E" and event == "approve" and _positive_total(record):
        return {
            "state": "A",
            "record": result_record,
            "audits": ["ORD_APPR"],
            "notifies": [],
            "matched": True,
        }

    if state == "A" and event == "ship":
        return {
            "state": "S",
            "record": result_record,
            "audits": ["ORD_SHIP"],
            "notifies": ["shipped"],
            "matched": True,
        }

    if state == "S" and event == "invoice":
        return {
            "state": "I",
            "record": result_record,
            "audits": ["ORD_INV"],
            "notifies": [],
            "matched": True,
        }

    if state == "E" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if (
        state == "A"
        and event == "cancel"
        and _lookup_credit_hold(record, tables) != "Y"
    ):
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC"],
            "notifies": [],
            "matched": True,
        }

    if state == "I" and event == "cancel":
        return {
            "state": "X",
            "record": result_record,
            "audits": ["ORD_CANC_INV"],
            "notifies": ["credit_note"],
            "matched": True,
        }

    return {
        "state": state,
        "record": result_record,
        "audits": ["WF_NOMATCH"],
        "notifies": [],
        "matched": False,
    }
